// frontend/src/features/tickets/TicketCard.jsx (New or Updated Component for Display)
// Use this in your ticket list/dashboard to show attachments
import React from "react";

const TicketCard = ({ ticket }) => {
  const { id, title, description, priority, status, created_at, attachments } = ticket;

  return (
    <div style={cardStyles.container}>
      <h3 style={cardStyles.title}>{title}</h3>
      <p style={cardStyles.description}>{description}</p>
      <div style={cardStyles.details}>
        <span><strong>Priority:</strong> {priority}</span>
        <span><strong>Status:</strong> {status}</span>
        <span><strong>Created:</strong> {new Date(created_at).toLocaleString()}</span>
      </div>

      {attachments && attachments.length > 0 ? (
        <div style={cardStyles.attachments}>
          <strong>Attachments:</strong>
          <ul style={cardStyles.list}>
            {attachments.map((att) => (
              <li key={att.id}>
                <a
                  href={att.file}
                  target="_blank"
                  rel="noopener noreferrer"
                  style={cardStyles.link}
                >
                  {att.file.split('/').pop() || "File"}
                </a>
              </li>
            ))}
          </ul>
        </div>
      ) : (
        <p style={cardStyles.noAttachments}>No attachments</p>
      )}
    </div>
  );
};

const cardStyles = {
  container: {
    border: "1px solid #ddd",
    padding: "20px",
    borderRadius: "12px",
    marginBottom: "20px",
    background: "#fff",
    boxShadow: "0 4px 12px rgba(0,0,0,0.05)",
  },
  title: {
    fontSize: "20px",
    margin: "0 0 12px",
    color: "#4527a0",
  },
  description: {
    margin: "0 0 16px",
    color: "#333",
  },
  details: {
    display: "flex",
    justifyContent: "space-between",
    flexWrap: "wrap",
    marginBottom: "12px",
    fontSize: "14px",
    color: "#555",
  },
  attachments: {
    marginTop: "12px",
  },
  list: {
    listStyle: "none",
    padding: 0,
    margin: "8px 0 0",
  },
  link: {
    color: "#7c4dff",
    textDecoration: "none",
  },
  noAttachments: {
    marginTop: "12px",
    fontStyle: "italic",
    color: "#777",
  },
};

export default TicketCard;
